using MediatR;using Namaa.Application.Abstractions.Persistence;using Namaa.Application.Invoices.Dtos;using Namaa.Domain.Common.Results;namespace Namaa.Application.Invoices.Queries.GetInvoices;public sealed class GetInvoicesQueryHandler(IInvoiceRepository repository):IRequestHandler<GetInvoicesQuery,Result<IReadOnlyList<InvoiceDto>>>{public async Task<Result<IReadOnlyList<InvoiceDto>>>Handle(GetInvoicesQuery request,CancellationToken cancellationToken)=>Result.Success<IReadOnlyList<InvoiceDto>>((await repository.GetAllAsync(cancellationToken)).Select(InvoiceDto.FromEntity).ToList());}
